  ('x² − 9 ifadesinin çarpanlarına ayrılmış biçimi aşağıdakilerden hangisidir?', '(x − 3)(x + 3)', ['(x − 3)²', '(x − 9)(x + 1)', '(x + 3)²'], 'İki kare farkı özdeşliği a² − b² = (a − b)(a + b) uygulanır: x² − 3² = (x − 3)(x + 3).'),
  ('(a + b)² açılımında ortadaki terim hangisidir?', '2ab', ['ab', 'a²b²', '4ab'], '(a + b)² = a² + 2ab + b² olduğundan ortadaki terim 2ab\'dir.'),
  ('x² − 5x + 6 üç terimlisinin çarpanlarından biri aşağıdakilerden hangisidir?', 'x − 2', ['x + 2', 'x − 6', 'x + 3'], 'Çarpımı 6, toplamı −5 olan sayılar −2 ve −3\'tür: x² − 5x + 6 = (x − 2)(x − 3).'),
  ('İki kare farkı özdeşliği kullanılarak 101² − 99² farkı hızlıca hesaplanırsa hangi sonuç elde edilir?', '400', ['200', '4', '2000'], '101² − 99² = (101 − 99)(101 + 99) = 2 · 200 = 400\'dür.'),
  ('Tam kare açılımından yararlanarak 49² sayısını (50 − 1)² biçiminde hesaplayan bir öğrenci hangi sonucu bulmalıdır?', '2401', ['2499', '2451', '2500'], '(50 − 1)² = 2500 − 100 + 1 = 2401\'dir.'),
  ('Zihinden çarpma için 53 · 47 çarpımı (50 + 3)(50 − 3) biçiminde düşünülürse sonuç kaçtır?', '2491', ['2509', '2500', '2501'], '(50 + 3)(50 − 3) = 2500 − 9 = 2491\'dir.'),
  ('(√7 + √2)(√7 − √2) çarpımının değeri hangisidir?', '5', ['9', '√5', '3'], 'İki kare farkı: (√7)² − (√2)² = 7 − 2 = 5.'),
  ('3(x − 2) − 2(x + 1) = 5 denklemini sağlayan x değeri nedir?', '13', ['3', '9', '−3'], '3x − 6 − 2x − 2 = 5 ⇒ x − 8 = 5 ⇒ x = 13\'tür.'),
  ('x = 2 değerinin kx − 5 = 3x + 1 denkleminin çözümü olması için k kaç olmalıdır?', '6', ['3', '4', '−6'], 'x = 2 yazılır: 2k − 5 = 7 ⇒ 2k = 12 ⇒ k = 6.'),
  ('Bir terazinin bir kefesinde 3 özdeş kutu ve 2 kg ağırlık, diğer kefesinde 1 kutu ve 8 kg ağırlık varken terazi dengededir. Bir kutu kaç kg\'dır?', '3', ['2', '5', '10/4'], '3x + 2 = x + 8 ⇒ 2x = 6 ⇒ x = 3 kg\'dır.'),
  ('x/2 + x/3 + x/6 = 12 denklemini çözen bir öğrenci sol tarafın neye eşit olduğunu fark ederek hemen x\'i bulur. x kaçtır?', '12', ['6', '72', '2'], '1/2 + 1/3 + 1/6 = 1 olduğundan sol taraf x\'tir; x = 12.'),
  ('Bir doğrusal denklemin çözümünde öğrenci 5x − 3 = 2x + 9 için önce her iki taraftan 2x çıkarıp ardından 3 eklemiştir. Bu iki adımdan sonra elde edilen eşitlik hangisidir?', '3x = 12', ['7x = 12', '3x = 6', '5x = 2x + 12'], '2x çıkarılınca 3x − 3 = 9, ardından 3 eklenince 3x = 12 olur.'),
  ('x + y = 10 ve x − y = 4 denklemlerinden oluşan sistemin çözümünde x ile y\'nin çarpımı nedir?', '21', ['24', '40', '28'], 'Denklemler taraf tarafa toplanınca 2x = 14 ⇒ x = 7, y = 3; çarpım 21\'dir.'),
  ('3a + 2b = 19 ve a + 2b = 9 olduğuna göre a + b toplamı nedir?', '7', ['5', '9', '14'], 'Denklemler çıkarılınca 2a = 10 ⇒ a = 5; ikinci denklemden 2b = 4 ⇒ b = 2. a + b = 7.'),
  ('Bir denklem sisteminde x = 2y ve 3x − y = 15 bilgisi verilmiştir. y değeri nedir?', '3', ['5', '6', '15/7'], 'x = 2y yazılırsa 6y − y = 15 ⇒ 5y = 15 ⇒ y = 3.'),
  ('Bir eşitsizliğin her iki tarafı negatif bir sayıyla çarpılırsa eşitsizlik yönü için ne olur?', 'Yön değişir', ['Yön aynı kalır', 'Eşitsizlik eşitliğe dönüşür', 'Yalnız sayı tamsa yön değişir'], 'Örneğin 2 < 3 iken −2 > −3 olur. Negatif sayıyla çarpma ya da bölme eşitsizliğin yönünü ters çevirir.'),
  ('−2x + 5 > 11 eşitsizliğini sağlayan x değerleri hangi aralıktadır?', 'x < −3', ['x > −3', 'x > 3', 'x < 3'], '−2x > 6 ⇒ her iki taraf −2\'ye bölünür ve yön değişir: x < −3.'),
  ('[−2, 5) aralığı aşağıdaki gösterimlerden hangisine karşılık gelir?', '−2 ≤ x < 5', ['−2 < x ≤ 5', '−2 < x < 5', '−2 ≤ x ≤ 5'], 'Köşeli parantez ucun dahil, normal parantez ucun hariç olduğunu gösterir.'),
  ('Bir taksi ücreti 40 TL açılış ve kilometre başına 25 TL\'dir. Ücretin 240 TL\'yi aşmaması için yolculuk en çok kaç km olabilir?', '8', ['9', '10', '7'], '40 + 25x ≤ 240 ⇒ 25x ≤ 200 ⇒ x ≤ 8 km.'),
  ('a, b, c farklı pozitif tam sayılar ve a + b + c = 20 olduğuna göre a\'nın alabileceği en büyük değer kaçtır?', '17', ['18', '16', '19'], 'a\'nın büyük olması için b ve c en küçük farklı pozitif değerler olan 1 ve 2 seçilir: a = 20 − 3 = 17.'),
  ('3 ≤ a ≤ 6 ve 2 ≤ b ≤ 4 olmak üzere a/b oranının alabileceği en büyük değer kaçtır?', '3', ['3/2', '3/4', '2'], 'Kesir pay en büyük, payda en küçükken en büyüktür: 6/2 = 3.'),
  ('Üç sayı 2, 3 ve 5 ile doğru orantılıdır: x/2 = y/3 = z/5. Sayıların toplamı 40 ise en büyük sayı z nedir?', '20', ['8', '12', '40/3'], 'Ortak oran k ise x = 2k, y = 3k, z = 5k; 10k = 40 ⇒ k = 4 ve z = 20.'),
  ('a/b = c/d orantısında içler çarpımı ile dışlar çarpımı için hangisi doğrudur?', 'ad = bc', ['ab = cd', 'ac = bd', 'a + d = b + c'], 'Bir orantıda dışlar çarpımı (a · d) içler çarpımına (b · c) eşittir.'),
  ('x ile y doğru orantılıdır ve x = 6 iken y = 15\'tir. x = 10 olduğunda y kaç olur?', '25', ['19', '9', '30'], 'y/x sabittir: 15/6 = 2,5. x = 10 için y = 25\'tir.'),
  ('x ile y ters orantılı iki çokluktur. x üç katına çıkarılırsa y nasıl değişir?', 'Üçte birine iner', ['Üç katına çıkar', '3 azalır', 'Değişmeden aynı kalır'], 'Ters orantıda x · y sabittir; x üç katına çıkarsa çarpımın sabit kalması için y üçte birine iner.'),
  ('a\'nın 3\'e oranı b\'nin 5\'e oranına eşittir. a\'nın iki katı ile b\'nin toplamı 33 ise b ile a arasındaki fark ne kadardır?', '6', ['3', '9', '15'], 'a = 3k, b = 5k ⇒ 6k + 5k = 11k = 33 ⇒ k = 3. b − a = 2k = 6.'),
  ('Hangi sayının 3 fazlasının yarısı, aynı sayının 6 eksiğine eşittir?', '15', ['9', '12', '18'], '(x + 3)/2 = x − 6 ⇒ x + 3 = 2x − 12 ⇒ x = 15.'),
  ('Toplamları 48 olan iki sayıdan büyüğü küçüğün 3 katından 4 fazladır. Küçük sayı kaçtır?', '11', ['12', '37', '16'], 'x + (3x + 4) = 48 ⇒ 4x = 44 ⇒ x = 11; büyük sayı 37\'dir.'),
  ('Bir öğrenci bir sayıyı 5 ile çarpacağına yanlışlıkla 5\'e bölmüş ve sonucu 6 bulmuştur. Doğru işlem yapılsaydı sonuç ne olurdu?', '150', ['30', '6/5', '750'], 'Sayı 6 · 5 = 30\'dur; doğru sonuç 30 · 5 = 150 olurdu.'),
  ('İki sayının toplamı 30, farkı 6\'dır. Bu sayıların çarpımı kaçtır?', '216', ['180', '234', '144'], 'Sayılar (30 + 6)/2 = 18 ve (30 − 6)/2 = 12\'dir; çarpımları 216\'dır.'),
  ('Üç sayının toplamı 60\'tır. Birinci sayı ikincinin 2 katı, üçüncü sayı ise birinci ile ikincinin toplamıdır. Üçüncü sayı kaçtır?', '30', ['20', '10', '40'], 'İkinci x ise birinci 2x, üçüncü 3x; 6x = 60 ⇒ x = 10, üçüncü sayı 30\'dur.'),
  ('Bir kavanozun 2/7\'si bal ile doludur. Kavanoza 300 gram bal eklendiğinde kavanozun 5/7\'si doluyor. Kavanozun tamamı kaç gram bal alır?', '700', ['420', '2100', '600'], 'Eklenen bal kavanozun 3/7\'sine karşılık gelir: 3/7 · x = 300 ⇒ x = 700 g.'),
  ('Bir otobüsteki yolcuların 1/4\'ü ilk durakta iniyor, ikinci durakta 6 kişi biniyor ve yolcu sayısı başlangıçtakine eşit oluyor. Başlangıçta kaç yolcu vardı?', '24', ['18', '30', '6'], 'İnenler 1/4 · x = 6 olmalıdır ki yolcu sayısı eski hâline dönsün; x = 24.'),
  ('Birler basamağı 5 olan bir sayının herhangi bir pozitif tam kuvvetinin birler basamağı için ne söylenebilir?', 'Her zaman 5\'tir', ['Her zaman 0\'dır', 'Kuvvete göre 5 ya da 0\'dır', 'Kuvvete göre 5 ya da 25\'tir'], '5 ile biten iki sayının çarpımı yine 5 ile biter; bu nedenle 5 ile biten sayıların bütün kuvvetleri 5 ile biter.'),
  ('10¹⁵ − 1 sayısı 9\'a bölündüğünde kalan kaçtır?', '0', ['1', '8', '6'], '10¹⁵ − 1 sayısı 15 tane 9\'dan oluşur (999...9); 9\'a tam bölünür ve kalan 0\'dır.'),
  ('Bir sayının 9\'a bölümünden kalan 4, 9\'a bölümünden elde edilen bölüm de 13\'tür. Aynı sayının 4\'e bölümünden kalan kaçtır?', '1', ['2', '3', '121'], 'Sayı 9 · 13 + 4 = 121\'dir; 121 = 4 · 30 + 1 olduğundan kalan 1\'dir.'),
  ('İkilik tabanda (1011)₂ biçiminde yazılan sayının onluk tabandaki karşılığı nedir?', '11', ['13', '1011', '9'], '1·2³ + 0·2² + 1·2 + 1 = 8 + 2 + 1 = 11\'dir.'),
  ('5 tabanında yazılmış bir sayıda kullanılabilecek en büyük rakam hangisidir?', '4', ['5', '9', '10'], 'n tabanında rakamlar 0\'dan n − 1\'e kadardır; 5 tabanında en büyük rakam 4\'tür.'),
  ('(x3)₅ = 18 eşitliğini sağlayan x rakamı kaçtır?', '3', ['2', '4', '15'], '(x3)₅ = 5x + 3 = 18 ⇒ x = 3\'tür.'),
  ('Sayı doğrusunda −7,5 ile 4,2 arasında kaç tam sayı vardır?', '12', ['11', '13', '10'], 'Bu aralıktaki tam sayılar −7\'den 4\'e kadardır: 4 − (−7) + 1 = 12.'),
  ('Sayı doğrusunda A noktası −3, B noktası 9\'dur. AB doğru parçasının orta noktası hangi sayıya karşılık gelir?', '3', ['6', '12', '−6'], 'Orta nokta uç değerlerin ortalamasıdır: (−3 + 9)/2 = 3.'),
  ('Sayı doğrusunda 2 ile 14 arasındaki uzaklık dört eş parçaya bölünüyor. 2\'den başlayarak ikinci bölme noktası hangi sayıdır?', '8', ['5', '11', '6'], 'Her parça (14 − 2)/4 = 3 birimdir; birinci nokta 5, ikinci nokta 8\'dir.'),
  ('Boş küme ile ilgili aşağıdaki ifadelerden hangisi doğrudur?', 'Boş küme her kümenin alt kümesidir', ['Boş kümenin hiç alt kümesi yoktur', '{0} kümesi boş kümedir', 'Boş küme yalnız kendisinin alt kümesidir'], 'Boş kümenin hiç elemanı olmadığından her kümenin alt kümesidir. {0} kümesinin bir elemanı vardır; boş değildir.'),
  ('A kümesi 12, B kümesi 9 elemanlıdır ve iki kümenin 4 ortak elemanı vardır. Birleşim kümesinde kaç eleman bulunur?', '17', ['21', '25', '13'], 's(A ∪ B) = s(A) + s(B) − s(A ∩ B) = 12 + 9 − 4 = 17.'),
  ('A = {a, b, c} ve B = {b, c, d, e} olduğuna göre A \\ B fark kümesi hangisidir?', '{a}', ['{d, e}', '{b, c}', '{a, d, e}'], 'A \\ B, A\'da olup B\'de olmayan elemanlardan oluşur; yalnız a bu koşulu sağlar.'),
  ('Evrensel küme E\'de A kümesinin tümleyeni A\' ile gösterilir. (A\')\' kümesi neye eşittir?', 'A', ['A\'', 'E', 'Boş küme'], 'Tümleyenin tümleyeni kümenin kendisidir: (A\')\' = A.'),
  ('Matematiksel mantıkta önerme, doğru ya da yanlış kesin bir hüküm bildiren ifadedir. Aşağıdakilerden hangisi bir önermedir?', '7 bir asal sayıdır.', ['Kapıyı kapatır mısın?', 'Ne güzel bir gün!', 'x + 2 = 5'], '"7 bir asal sayıdır." ifadesinin doğruluk değeri kesindir. Soru ve ünlem cümleleri hüküm bildirmez; x + 2 = 5 ise x\'e bağlı olduğundan açık önermedir.'),
  ('Doğruluk değeri 1 olan p önermesi ile doğruluk değeri 0 olan q önermesi "ve" bağlacıyla birleştiriliyor. p ∧ q önermesinin doğruluk değeri nedir?', '0', ['1', 'p\'nin değerine eşittir', 'Belirlenemez'], '"Ve" bağlacıyla kurulan önerme yalnız iki bileşen de doğru (1) olduğunda doğrudur; q\'nun değeri 0 olduğundan sonuç 0\'dır.'),
  ('p ⇔ q (ancak ve ancak) önermesi hangi durumda doğrudur?', 'İkisi aynı değeri aldığında', ['Yalnız p doğruyken', 'p ile q farklı doğruluk değerindeyken', 'Yalnız q yanlışken'], 'İki yönlü koşullu önerme bileşenlerin ikisi de doğru ya da ikisi de yanlış olduğunda doğrudur.'),
  ('İşlem önceliği kurallarına göre 18 − 6 : 3 · 2 + 1 işleminin sonucu kaçtır?', '15', ['5', '9', '13'], 'Çarpma ve bölme soldan sağa yapılır: 6 : 3 = 2, 2 · 2 = 4. Ardından 18 − 4 + 1 = 15.'),
  ('Üs alma işleminin önceliği dikkate alındığında 2 + 3 · 4² ifadesinin değeri nedir?', '50', ['146', '400', '56'], 'Önce üs: 4² = 16; sonra çarpma: 3 · 16 = 48; en son toplama: 2 + 48 = 50.'),
  ('4 768 sayısı yüzler basamağına göre yuvarlanırsa hangi sayı elde edilir?', '4 800', ['4 700', '5 000', '4 770'], 'Yüzler basamağından sonraki onlar rakamı 6 ≥ 5 olduğundan yukarı yuvarlanır: 4 800.'),
  ('Bilimsel gösterimde a · 10ⁿ yazılırken a katsayısı hangi koşulu sağlamalıdır?', '1 ≤ |a| < 10', ['0 < |a| < 1', '1 < |a| ≤ 10', '|a| ≥ 10 ya da |a| < 1'], 'Bilimsel gösterimde katsayının mutlak değeri 1\'e eşit ya da 1\'den büyük, 10\'dan küçük olmalıdır.'),
  ('0,000 052 sayısının bilimsel gösterimi aşağıdakilerden hangisidir?', '5,2 · 10⁻⁵', ['5,2 · 10⁻⁶', '0,52 · 10⁻⁴', '5,2 · 10⁵'], 'Virgül 5 basamak sağa kaydırılınca 5,2 elde edilir; bu nedenle üs −5\'tir.'),
  ('3,14159 sayısı virgülden sonra iki basamağa yuvarlandığında elde edilen değer hangisidir?', '3,14', ['3,15', '3,141', '3,1'], 'Üçüncü ondalık basamaktaki rakam 1 < 5 olduğundan aşağı yuvarlanır: 3,14.'),
  ('x sayısının 8\'e bölümünden kalan 5, y sayısının 8\'e bölümünden kalan 6\'dır. x + y toplamının 8\'e bölümünden kalan kaçtır?', '3', ['11', '5', '7'], 'Kalanlar toplanır: 5 + 6 = 11; 11\'in 8\'e bölümünden kalan 3\'tür.'),
  ('a sayısının 5\'e bölümünden kalan 3\'tür. 2a + 4 sayısının 5\'e bölümünden kalan kaçtır?', '0', ['10', '1', '3'], '2 · 3 + 4 = 10 ve 10\'un 5\'e bölümünden kalan 0\'dır.'),
  ('A sayısının 9\'a bölümünden kalan 7, B sayısının 9\'a bölümünden kalan 5\'tir. A · B çarpımının 9\'a bölümünden kalan kaçtır?', '8', ['35', '2', '3'], 'Kalanlar çarpılır: 7 · 5 = 35 = 3 · 9 + 8 ⇒ kalan 8.'),
  ('84/126 kesrinin en sade biçimi aşağıdakilerden hangisidir?', '2/3', ['4/6', '14/21', '42/63'], 'EBOB(84, 126) = 42\'dir; pay ve payda 42\'ye bölününce 2/3 elde edilir. Diğer seçenekler denk ama sadeleşebilir kesirlerdir.'),
  ('3/5 kesrine denk olan ve paydası 45 olan kesrin payı kaçtır?', '27', ['9', '15', '43'], '45 = 5 · 9 olduğundan pay da 9 ile çarpılır: 3 · 9 = 27.'),
  ('Aşağıdaki kesirlerden hangisi 0,75\'e denk değildir?', '15/25', ['75/100', '21/28', '30/40'], '9/12, 21/28 ve 30/40 sadeleşince 3/4 = 0,75 olur. 15/25 ise 3/5 = 0,6\'dır.'),
  ('Bir kesrin payı ve paydası aynı sayıyla çarpılırsa kesrin değeri için ne söylenebilir? (Çarpan sıfırdan farklıdır.)', 'Değişmez', ['Çarpan kadar artar', 'Çarpanın karesi kadar artar', 'Pay büyürse kesir de büyür'], 'Pay ve payda aynı sıfırdan farklı sayıyla çarpılırsa kesir k/k = 1 ile çarpılmış olur; değer değişmez, denk bir kesir elde edilir.'),
  ('0,375 ondalık sayısının en sade kesir biçimi hangisidir?', '3/8', ['375/100', '3/80', '37/100'], '0,375 = 375/1000\'dir; 125 ile sadeleştirilince 3/8 olur.'),
  ('Bir ölçümde 1,25 m uzunluğundaki bir şerit kesir olarak kaç metredir?', '5/4', ['5/2', '125/10', '4/5'], '1,25 = 125/100 = 5/4 metredir.'),
  ('0,12 · 25 işlemi kesirlerle yapılırsa sonuç hangi kesirle gösterilir?', '3', ['3/10', '12/25', '30'], '0,12 = 3/25 olduğundan 3/25 · 25 = 3\'tür.'),
  ('Çarpımı 48 olan iki pozitif tam sayıdan büyüğünden küçüğü çıkarılıyor. Bu farkın ulaşabileceği en yüksek değer nedir?', '47', ['46', '24', '2'], 'Fark en büyük olsun diye a = 48, b = 1 seçilir: 48 − 1 = 47.'),
  ('Rakamları farklı dört basamaklı bir sayının rakamları toplamı en çok kaç olabilir?', '30', ['36', '24', '32'], 'Farklı en büyük dört rakam 9, 8, 7, 6\'dır; toplamları 30\'dur.'),
  ('İki sayının toplamı 84 ve oranı 3/4\'tür. Büyük sayı kaçtır?', '48', ['36', '63', '12'], 'Sayılar 3k ve 4k ise 7k = 84 ⇒ k = 12; büyük sayı 48\'dir.'),
  ('İki sayının farkı 18\'dir. Büyük sayı küçük sayının 4 katı olduğuna göre toplamları kaçtır?', '30', ['24', '36', '72'], 'Küçük x ise 4x − x = 18 ⇒ x = 6. Sayılar 6 ve 24, toplamları 30.'),
  ('İki sayının aritmetik ortalaması 15, büyük olanın küçük olana oranı 2\'dir. Küçük sayı kaçtır?', '10', ['15', '20', '7,5'], 'Toplam 30\'dur. Küçük x ise x + 2x = 30 ⇒ x = 10.'),
  ('Toplamları 30 olan iki doğal sayının çarpımı en çok kaç olabilir?', '225', ['224', '200', '900'], 'Toplam sabitken sayılar eşit olduğunda çarpım en büyüktür: 15 · 15 = 225.'),
  ('Bir kalem bir silginin 3 katı fiyatındadır. 2 kalem ile 5 silgi toplam 66 TL tuttuğuna göre bir kalem kaç TL\'dir?', '18', ['6', '22', '13,2'], 'Silgi s ise 2 · 3s + 5s = 11s = 66 ⇒ s = 6 TL; kalem 18 TL\'dir.'),
  ('Bir sınıftaki kızların sayısı erkeklerin sayısının 2 katından 3 eksiktir. Sınıf mevcudu 33 ise sınıfta kaç kız vardır?', '21', ['12', '15', '19'], 'Erkek e ise e + (2e − 3) = 33 ⇒ 3e = 36 ⇒ e = 12; kız sayısı 21.'),
  ('Üç kardeşin paraları toplamı 1800 TL\'dir. Birincinin parası ikincinin yarısı, üçüncünün de üçte biri kadardır. Üçüncü kardeşin kaç TL\'si vardır?', '900', ['600', '300', '1200'], 'Birincinin parası a ise ikinci 2a, üçüncü 3a\'dır: 6a = 1800 ⇒ a = 300; üçüncü kardeş 900 TL\'ye sahiptir.'),
  ('Bir babanın 3 çocuğuna verdiği harçlıklar ardışık çift sayılardır ve toplamları 150 TL\'dir. En küçük çocuğun harçlığı kaç TL\'dir?', '48', ['50', '46', '52'], 'Harçlıklar x, x + 2, x + 4 ise 3x + 6 = 150 ⇒ x = 48 TL.'),
  ('Bir sayının 3 fazlasının, aynı sayının 3 eksiğine oranı 2\'dir. Bu sayı kaçtır?', '9', ['6', '3', '12'], '(x + 3)/(x − 3) = 2 ⇒ x + 3 = 2x − 6 ⇒ x = 9.'),
  ('Bir terzi bir top kumaştan önce 3 m, sonra kalan kumaşın yarısını kesiyor. Geriye 6 m kumaş kaldığına göre başlangıçta kaç metre kumaş vardı?', '15', ['12', '18', '9'], '3 m kesildikten sonra kalan k ise k/2 = 6 ⇒ k = 12; başlangıç uzunluğu 12 + 3 = 15 m\'dir.'),
  ('Gece sıcaklığı −7 °C olan bir kentte öğlen sıcaklığı 12 °C\'ye çıkmıştır. Sıcaklık kaç derece artmıştır?', '19', ['5', '−19', '−5'], 'Artış son değer ile ilk değerin farkıdır: 12 − (−7) = 19 °C.'),
  ('Negatif sayılarla bölme ve çarpma içeren (−48) : (−6) − (−3) · 4 ifadesinde işaret kurallarını uygulayınca hangi sayı bulunur?', '20', ['−4', '4', '−20'], '(−48) : (−6) = 8; (−3) · 4 = −12. 8 − (−12) = 20.'),
  ('Bir dalgıç deniz seviyesinin 18 m altındadır. Önce 7 m yukarı çıkıp sonra 12 m aşağı inerse deniz seviyesine göre konumu ne olur?', '−23 m', ['−13 m', '23 m', '−37 m'], '−18 + 7 − 12 = −23; dalgıç deniz seviyesinin 23 m altındadır.'),
  ('Beş çarpandan üçünün negatif olduğu −1 · 2 · (−3) · 4 · (−5) çarpımı hangi değeri verir?', '−120', ['120', '−60', '60'], 'Üç negatif çarpan vardır; tek sayıda negatif çarpan sonucu negatif yapar. 1 · 2 · 3 · 4 · 5 = 120 ⇒ −120.'),
  ('Bir asansör 3. bodrum kattan (−3) yukarı 9 kat çıkıyor, ardından 4 kat iniyor. Asansör hangi katta durur?', '2. kat', ['−2. kat', '6. kat', '10. kat'], '−3 + 9 − 4 = 2; asansör 2. katta durur.'),
  ('Bir öğrenci −3 − 5 işleminin sonucunu 2 bulmuştur. Öğrencinin yaptığı hata hangisidir?', '5 − 3 işlemini yapmıştır', ['Sonuç doğrudur', 'Toplama yerine çarpma yapmıştır', 'Sonucun işaretini ters yazmıştır'], 'Doğru sonuç −3 − 5 = −8\'dir. 2 sonucu 5 − 3 işleminden gelir; öğrenci işaretleri karıştırmıştır.'),
  ('Köklü sayıların çarpımı ve bölümü kurallarıyla √12 · √27 / √9 hesaplanırsa sonuç ne çıkar?', '6', ['18', '2√3', '√36/3'], '√12 · √27 = √324 = 18; 18 / 3 = 6.'),
  ('Gerçek sayılarda çarpma işlemine göre tersi olmayan tek sayı hangisidir?', '0', ['1', '−1', 'Hiçbir sayı'], 'a · x = 1 eşitliğini sağlayan x, a = 0 için bulunamaz; çünkü 0 ile çarpılan her sayı 0 olur.'),
  ('Gerçek sayılarda çarpma işleminin etkisiz (birim) elemanı hangisidir?', '1', ['0', '−1', 'Sayının tersi'], 'Her a için a · 1 = 1 · a = a olduğundan çarpmanın etkisiz elemanı 1\'dir. Toplamanın etkisiz elemanı ise 0\'dır.'),
  ('Bir öğrenci 7 · 23 çarpımını 7 · 20 + 7 · 3 biçiminde zihinden hesaplıyor. Öğrencinin kullandığı özellik hangisidir?', 'Çarpmanın toplama üzerine dağılma özelliği', ['Toplamanın değişme özelliği', 'Çarpmanın birleşme özelliği', 'Çarpmada etkisiz eleman özelliği'], 'a(b + c) = ab + ac biçimindeki kural, çarpmanın toplama üzerine dağılma özelliğidir.'),
  ('Aşağıdaki işlemlerden hangisinde değişme özelliği yoktur, yani a ile b\'nin yeri değişince sonuç değişebilir?', 'Çıkarma', ['Toplama', 'Çarpma', 'Toplama ile çarpmanın ikisi'], '5 − 3 = 2 iken 3 − 5 = −2\'dir; çıkarmada değişme özelliği yoktur. Toplama ve çarpma değişmelidir.'),
  ('Bir doğal sayının küpü biçiminde yazılabilen sayılara tam küp denir. İki basamaklı kaç tane tam küp vardır?', '2', ['3', '1', '4'], '3³ = 27 ve 4³ = 64 iki basamaklıdır; 2³ = 8 tek, 5³ = 125 üç basamaklıdır. Toplam 2 tane.'),
  ('Beş basamaklı en küçük doğal sayı ile dört basamaklı en büyük doğal sayının farkı kaçtır?', '1', ['0', '9', '2'], 'Beş basamaklı en küçük sayı 10 000, dört basamaklı en büyük sayı 9 999\'dur; fark 1\'dir.'),
  ('Toplamları çift olan iki asal sayının çarpımı için hangisi her zaman doğrudur? (İki sayı da 2\'den büyüktür.)', 'Tek sayıdır', ['Çift sayıdır', 'Asal sayıdır', 'Tam karedir'], '2\'den büyük asallar tektir; iki tek sayının çarpımı da tektir.'),
  ('Üç ondalık sayının çarpımı olan 0,2 · 0,3 · 0,5 işleminin sonucu nedir?', '0,03', ['0,3', '0,003', '3'], '2 · 3 · 5 = 30; virgülden sonra toplam 3 basamak vardır: 0,030 = 0,03.'),
  ('İlk on tek sayının toplamının karekökü, yani √(1 + 3 + 5 + ... + 19) kaçtır?', '10', ['√190', '100', '9'], 'İlk 10 tek sayının toplamı 10² = 100 olduğundan karekökü 10\'dur.'),
  ('50 < n < 150 koşulunu sağlayan ve karekökü tam sayı olan kaç n doğal sayısı vardır?', '5', ['4', '6', '100'], 'Aralıktaki tam kareler 64, 81, 100, 121 ve 144\'tür; toplam 5 tane.'),
  ('Dokuza bölme işleminde bölümü 15, kalanı 7 olan sayıyı bulup sekize bölen bir öğrenci hangi kalanı elde eder?', '6', ['7', '10', '142'], 'Sayı 9 · 15 + 7 = 142\'dir; 142 = 8 · 17 + 6 olduğundan kalan 6\'dır.'),
  ('(2 + 4 + 6 + ... + 20) / (1 + 2 + 3 + ... + 10) bölümünün değeri hangisidir?', '2', ['1/2', '10', '20'], 'Paydaki her terim paydadaki karşılığının 2 katıdır; bu yüzden pay paydanın 2 katıdır ve bölüm 2 olur.'),
];
